def test_integer_range_accepts_lower_bound():
    import click
    from click.testing import CliRunner

    received = []

    @click.command()
    @click.option("--count", type=click.IntRange(1, 3))
    def cli(count):
        received.append(count)

    result = CliRunner().invoke(cli, ["--count", "1"])

    assert result.exit_code == 0
    assert received == [1]
    assert isinstance(received[0], int)
    assert not isinstance(received[0], bool)

